#!/usr/bin/env node
/**
 * BudStacks template validator (Template Design System v2).
 *
 * Usage:
 *   node scripts/validate-template.mjs <template-folder> [<template-folder> …]
 *   node scripts/validate-template.mjs --json <template-folder>
 *
 * Needs Node 20 or later and nothing else: no install step, no network.
 * Exit code 0 when no template has errors, 1 otherwise (warnings never fail).
 *
 * It checks against references/contract/, which is generated by the platform.
 * Refresh it with scripts/sync-contract.sh when budstack-saas changes.
 */
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { loadContract, validateTemplate } from "./lib/validate.mjs";

const here = dirname(fileURLToPath(import.meta.url));
const CONTRACT_DIR = join(here, "..", "references", "contract");

function main() {
  const args = process.argv.slice(2);
  const asJson = args.includes("--json");
  const folders = args.filter((arg) => !arg.startsWith("--"));
  if (folders.length === 0) {
    console.error("usage: node scripts/validate-template.mjs [--json] <template-folder> …");
    process.exit(2);
  }

  let contract;
  try {
    contract = loadContract(CONTRACT_DIR);
  } catch (error) {
    console.error(`Could not read the contract in ${CONTRACT_DIR}: ${error instanceof Error ? error.message : String(error)}`);
    console.error("Run scripts/sync-contract.sh <path-to-budstack-saas> first.");
    process.exit(2);
  }

  const reports = folders.map((folder) => ({ folder, ...validateTemplate(resolve(folder), contract) }));
  if (asJson) {
    console.log(JSON.stringify(reports, null, 2));
  } else {
    for (const report of reports) {
      const verdict = report.errors.length === 0 ? "PASS" : "FAIL";
      console.log(`\n${verdict}  ${report.folder}  (${report.errors.length} errors, ${report.warnings.length} warnings)`);
      for (const error of report.errors) console.log(`  error    ${error}`);
      for (const warning of report.warnings) console.log(`  warning  ${warning}`);
    }
    console.log("");
  }
  // Not process.exit(): on a pipe that can cut a long report short.
  process.exitCode = reports.some((report) => report.errors.length > 0) ? 1 : 0;
}

main();
